import{_ as i,c as a,a0 as l,o as d}from"./chunks/framework.B6JXc2q-.js";const y=JSON.parse('{"title":"v1.1.1 发布说明","description":"","frontmatter":{},"headers":[],"relativePath":"release/v1.1.1.md","filePath":"release/v1.1.1.md"}'),t={name:"release/v1.1.1.md"};function o(c,e,r,n,s,_){return d(),a("div",null,e[0]||(e[0]=[l('<h1 id="v1-1-1-发布说明" tabindex="-1">v1.1.1 发布说明 <a class="header-anchor" href="#v1-1-1-发布说明" aria-label="Permalink to &quot;v1.1.1 发布说明&quot;">​</a></h1><p>发布日期：2026-04-26<br> 适用分支：<code>main</code></p><hr><h2 id="_1-本次发布的基线" tabindex="-1">1. 本次发布的基线 <a class="header-anchor" href="#_1-本次发布的基线" aria-label="Permalink to &quot;1. 本次发布的基线&quot;">​</a></h2><p>v1.1.1 的描述基于 <strong><code>v1.1.0</code> tag 与当前工作树的代码差异</strong>，不是沿用口头结论倒推。</p><p>本次对比基线：</p><ul><li>旧版本：<code>v1.1.0</code></li><li>当前版本：<code>v1.1.1</code></li><li>参考命令：<code>git diff --stat v1.1.0..HEAD</code></li></ul><hr><h2 id="_2-相对-v1-1-0-的真实变化" tabindex="-1">2. 相对 v1.1.0 的真实变化 <a class="header-anchor" href="#_2-相对-v1-1-0-的真实变化" aria-label="Permalink to &quot;2. 相对 v1.1.0 的真实变化&quot;">​</a></h2><h3 id="_2-1-webui-歌单选择状态彻底整改" tabindex="-1">2.1 WebUI 歌单选择状态彻底整改 <a class="header-anchor" href="#_2-1-webui-歌单选择状态彻底整改" aria-label="Permalink to &quot;2.1 WebUI 歌单选择状态彻底整改&quot;">​</a></h3><p>v1.1.0 的 WebUI pending selection 生命周期逻辑在实机验收时暴露了结构性缺陷：歌曲 selector 使用 <code>key={item.id}</code>，但后端 <code>/api/v1/library/playlists</code> 返回的 track id 可能重复，导致 React <code>&lt;option&gt;</code> 残留、列表重复/错位/不可选。</p><p>本次整改不止于前端止血，而是彻底引入 identity 体系：</p><ul><li>前端：<code>HomePage.tsx</code> 歌曲 selector key 改为 <code>${effectivePlaylist}:${item.id}:${idx}</code></li><li>后端：建立 <code>music_entities</code> / <code>playlist_memberships</code> / <code>playlist_definitions</code> 主模型，替代 <code>all_music={name:url}</code> / <code>music_list={playlist:[name]}</code> 的 name-based 旧结构</li><li>API：<code>/api/v1/library/playlists</code> 优先输出 membership 结构与 <code>entity_id</code>，不再基于 filepath/url 生成重复 track id</li></ul><h3 id="_2-2-设备运行态-identity-化" tabindex="-1">2.2 设备运行态 identity 化 <a class="header-anchor" href="#_2-2-设备运行态-identity-化" aria-label="Permalink to &quot;2.2 设备运行态 identity 化&quot;">​</a></h3><p><code>config.py</code> 的 <code>Device</code> 类新增三个显式 identity 槽位：</p><ul><li><code>current_entity_id</code></li><li><code>current_playlist_item_id</code></li><li><code>current_display_name</code></li></ul><p><code>device_player.py</code> 开始维护结构化 <code>_play_list_items</code>（list[dict]），并提供：</p><ul><li><code>_build_playlist_runtime_items()</code>：从 membership 或 legacy <code>music_list</code> 构建结构化列表</li><li><code>_find_playlist_index()</code>：<strong>优先按 <code>playlist_item_id → entity_id → display_name → legacy_name → index fallback</code></strong> 定位，不再仅靠 <code>_play_list.index(name)</code></li><li><code>_set_runtime_track_reference()</code> / <code>get_current_track_reference()</code></li></ul><p>external URL bootstrap 也已改为优先按 <code>playlist_item_id → entity_id → display_name</code> 对位。</p><h3 id="_2-3-legacy-api-identity-收口" tabindex="-1">2.3 Legacy API identity 收口 <a class="header-anchor" href="#_2-3-legacy-api-identity-收口" aria-label="Permalink to &quot;2.3 Legacy API identity 收口&quot;">​</a></h3><p><code>/playingmusic</code> 与 <code>/ws/playingmusic</code> 改为基于 <code>PlaybackFacade.build_player_state_snapshot()</code> 投影，兼容返回中新增：</p><ul><li><code>entity_id</code></li><li><code>playlist_item_id</code></li><li><code>current_index</code></li><li><code>context_id</code></li></ul><p><code>/api/v1/library/music-info</code> 与 <code>/musicinfo</code> 开始接受 <code>entity_id</code> 查询；若只给 <code>entity_id</code>，通过 <code>get_legacy_name_for_entity()</code> 解析展示名再回查 URL/tags。</p><h3 id="_2-4-favorites-entity-全链路" tabindex="-1">2.4 Favorites entity 全链路 <a class="header-anchor" href="#_2-4-favorites-entity-全链路" aria-label="Permalink to &quot;2.4 Favorites entity 全链路&quot;">​</a></h3><ul><li><code>FavoritesRequest</code> 新增 <code>entity_id</code> 字段，<code>/api/v1/library/favorites/add|remove</code> 优先透传 <code>entity_id</code>，避免同名歌曲加入/移出收藏时继续只靠 <code>track_name</code> 判等</li><li>旧 <code>/playlistaddmusic</code> 等路由的 <code>PlayListMusicObj.music_list</code> 开始接受 <code>{entity_id, display_name}</code> 结构，便于老入口平滑过渡到 entity 引用</li><li><code>play_list_add_music(&#39;收藏&#39;, ...)</code> 修复：<code>收藏</code> 原被保留名拦截无法自动创建；新建歌单后现在会重新获取 <code>custom_play_list</code> 引用，避免后续 append 写到旧引用里导致条目丢失</li></ul><h3 id="_2-5-source-plugin-identity-接受能力" tabindex="-1">2.5 Source plugin identity 接受能力 <a class="header-anchor" href="#_2-5-source-plugin-identity-接受能力" aria-label="Permalink to &quot;2.5 Source plugin identity 接受能力&quot;">​</a></h3><p><code>PlaybackFacade</code> 在标题兜底前优先解析 <code>entity_id</code>，<code>local_library_source_plugin</code> 优先接受 payload <code>entity_id</code>。</p><hr><h2 id="_3-文档层更新" tabindex="-1">3. 文档层更新 <a class="header-anchor" href="#_3-文档层更新" aria-label="Permalink to &quot;3. 文档层更新&quot;">​</a></h2><ul><li><code>docs/architecture/webui_playlist_state.md</code> 更新到 v1.4（2026-04-26）</li><li><code>docs/index.md</code> 更新当前阅读路径与发布说明入口</li><li><code>README.md</code> 更新发布说明入口</li></ul><hr><h2 id="_4-当前已确认的范围" tabindex="-1">4. 当前已确认的范围 <a class="header-anchor" href="#_4-当前已确认的范围" aria-label="Permalink to &quot;4. 当前已确认的范围&quot;">​</a></h2><h3 id="_4-1-webui-playlist-identity" tabindex="-1">4.1 WebUI / Playlist identity <a class="header-anchor" href="#_4-1-webui-playlist-identity" aria-label="Permalink to &quot;4.1 WebUI / Playlist identity&quot;">​</a></h3><ul><li><code>HomePage.tsx</code> 歌曲 selector key 已改为唯一组合 key</li><li><code>music_entities</code> / <code>playlist_memberships</code> / <code>playlist_definitions</code> 主模型已在 MusicLibrary 中建立</li><li>聚合歌单（<code>所有歌曲</code>/<code>全部</code>/<code>日语</code>/<code>中文</code>）已按 entity 去重，无重复 id/entity_id</li><li>影子澪审核通过（2026-04-26）</li></ul><h3 id="_4-2-设备运行态" tabindex="-1">4.2 设备运行态 <a class="header-anchor" href="#_4-2-设备运行态" aria-label="Permalink to &quot;4.2 设备运行态&quot;">​</a></h3><ul><li><code>Device</code> 三槽位已落地</li><li><code>device_player.py</code> 结构化播放列表与完整定位链已落地</li><li>external URL bootstrap 已优先按 item → entity → display_name 对位</li></ul><h3 id="_4-3-legacy-api" tabindex="-1">4.3 Legacy API <a class="header-anchor" href="#_4-3-legacy-api" aria-label="Permalink to &quot;4.3 Legacy API&quot;">​</a></h3><ul><li><code>/playingmusic</code> 与 <code>/ws/playingmusic</code> 已返回 identity 字段</li><li><code>/api/v1/library/music-info</code> 与 <code>/musicinfo</code> 已支持 entity_id 查询</li></ul><h3 id="_4-4-favorites" tabindex="-1">4.4 Favorites <a class="header-anchor" href="#_4-4-favorites" aria-label="Permalink to &quot;4.4 Favorites&quot;">​</a></h3><ul><li>entity_id 优先透传已落地</li><li><code>收藏</code> backing playlist 新建逻辑已修复</li><li>新建后重新获取 <code>custom_play_list</code> 引用已落地</li></ul><h3 id="_4-5-回归测试" tabindex="-1">4.5 回归测试 <a class="header-anchor" href="#_4-5-回归测试" aria-label="Permalink to &quot;4.5 回归测试&quot;">​</a></h3><ul><li>17 个 identity 相关 Python 测试全部通过</li><li>WebUI 测试 21/21 通过</li><li>本地全量测试通过</li></ul><hr><h2 id="_5-当前未完成或仍需如实保留的边界" tabindex="-1">5. 当前未完成或仍需如实保留的边界 <a class="header-anchor" href="#_5-当前未完成或仍需如实保留的边界" aria-label="Permalink to &quot;5. 当前未完成或仍需如实保留的边界&quot;">​</a></h2><ul><li><code>disabled_plugins</code> 当前仍为内存态，不持久化</li><li>HomePage 状态逻辑仍偏集中，后续建议拆出独立 hooks</li><li>pending invalidation 仍依赖前端本地判据组合，若后端某些路径存在投影延迟，仍可能出现边界误差</li></ul><hr><h2 id="_6-本次发布确认的是哪一层-不是哪一层" tabindex="-1">6. 本次发布确认的是哪一层，不是哪一层 <a class="header-anchor" href="#_6-本次发布确认的是哪一层-不是哪一层" aria-label="Permalink to &quot;6. 本次发布确认的是哪一层，不是哪一层&quot;">​</a></h2><h3 id="本次发布确认的是" tabindex="-1">本次发布确认的是 <a class="header-anchor" href="#本次发布确认的是" aria-label="Permalink to &quot;本次发布确认的是&quot;">​</a></h3><ul><li>WebUI 歌曲 selector 重复 key 问题已修复</li><li>音乐库 identity 主模型已建立，name-based 旧结构已替换</li><li>设备运行态 identity 化已完成</li><li>Legacy API identity 收口已完成</li><li>Favorites entity 全链路已完成</li></ul><h3 id="本次发布没有确认的不是" tabindex="-1">本次发布没有确认的不是 <a class="header-anchor" href="#本次发布没有确认的不是" aria-label="Permalink to &quot;本次发布没有确认的不是&quot;">​</a></h3><ul><li>identity 体系的最终完整形态（A-F 剩余清单中仍有部分未竟项）</li><li>所有播放路径与所有来源的长期稳定性总验收</li></ul>',51)]))}const h=i(t,[["render",o]]);export{y as __pageData,h as default};
